import path from 'node:path';
import { DATA_SCHEMA_VERSION } from '@gamebacklog/shared';
import { eq } from 'drizzle-orm';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import type { AppDatabase } from './client.ts';
import { schemaMeta } from './schema/index.ts';

/** Versioned SQL migrations generated by `pnpm db:generate` (apps/server/drizzle). */
export const MIGRATIONS_FOLDER = path.resolve(import.meta.dirname, '../../drizzle');

export const DATA_SCHEMA_VERSION_KEY = 'data_schema_version';

/** Applies pending migrations and records the data schema version. Safe to run on every start. */
export function runMigrations(db: AppDatabase): void {
  migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });

  const version = String(DATA_SCHEMA_VERSION);
  db.insert(schemaMeta)
    .values({ key: DATA_SCHEMA_VERSION_KEY, value: version })
    .onConflictDoUpdate({ target: schemaMeta.key, set: { value: version } })
    .run();
}

/** Data schema version recorded in the database, or null before the first migration. */
export function readDataSchemaVersion(db: AppDatabase): number | null {
  const row = db
    .select({ value: schemaMeta.value })
    .from(schemaMeta)
    .where(eq(schemaMeta.key, DATA_SCHEMA_VERSION_KEY))
    .get();
  return row ? Number(row.value) : null;
}
